if (!Array.isArray(snapshot) || snapshot.length !== 2) {
  throw new Error("Snapshot LAB invalido.");
}

return snapshot.map((contexto) => ({
  json: {
    ...contexto,
    snapshot_mode: true,
    snapshot_origin: "LOCAL_POSTGRESQL_EXPORT",
    runtime_database_query: false
  }
}));

const registros = $input.all();

return registros.map((item) => {

  const contexto = item.json;

  if (
    contexto.environment !== "LAB" ||
    contexto.processor !== "WF-03"
  ) {
    throw new Error("Contexto fora do escopo LAB.");
  }

  if (
    contexto.schema_version !== "1.0" ||
    !contexto.investigation_id ||
    !contexto.queue_id
  ) {
    throw new Error("Contrato de contexto invalido.");
  }

  const versaoHistorica =
    contexto.requested_version <
    contexto.current_version;

  if (
    contexto.is_historical_version !== versaoHistorica
  ) {
    throw new Error(
      "Inconsistencia no versionamento."
    );
  }

  const elegivel =
    contexto.queue_status === "PENDING" &&
    !versaoHistorica;

  if (
    contexto.eligible_for_context_review !== elegivel
  ) {
    throw new Error(
      "Inconsistencia na elegibilidade."
    );
  }

  if (
    !Array.isArray(contexto.event?.evidence) ||
    contexto.event.evidence.length !==
      contexto.evidence_count
  ) {
    throw new Error(
      "Quantidade de evidencias inconsistente."
    );
  }

  const statusEsperado = versaoHistorica
    ? "HISTORICAL_VERSION"
    : elegivel
      ? "READY_FOR_REVIEW"
      : "NOT_PENDING";

  if (contexto.context_status !== statusEsperado) {
    throw new Error(
      "Status do contexto inconsistente."
    );
  }

  // Validar a integridade do contexto para o WF-04.

  if (
    !contexto.event ||
    typeof contexto.event !== "object" ||
    !contexto.event.source_event_id ||
    !contexto.event.event_type ||
    !contexto.event.severity ||
    !contexto.event.occurred_at
  ) {
    throw new Error(
      "Evento normalizado incompleto."
    );
  }

  if (
    contexto.event.source_event_id !==
    contexto.source_event_id
  ) {
    throw new Error(
      "Identidade divergente entre contexto e evento."
    );
  }

  if (
    !Array.isArray(contexto.changed_fields) ||
    !contexto.provenance?.content_signature
  ) {
    throw new Error(
      "Metadados de versao e proveniencia ausentes."
    );
  }


  if (
    contexto.ai_executed !== false ||
    contexto.dispatch_status !== "MOCK_ONLY"
  ) {
    throw new Error(
      "Execucao nao autorizada detectada."
    );
  }

  return {
    json: {
      ...contexto,
      validation: {
        status: "VALID",
        checked_at: new Date().toISOString(),
        calculated_eligibility: elegivel
      }
    }
  };

});

const registros = $input.all();

return registros.map((item) => {

  const contexto = item.json;

  if (contexto.validation?.status !== "VALID") {
    throw new Error(
      "Contexto nao validado."
    );
  }

  const elegivel =
    contexto.validation.calculated_eligibility;

  return {
    json: {
      schema_version: "1.0",
      environment: "LAB",
      processor: "WF-03",

      queue_id: contexto.queue_id,

      investigation_id:
        contexto.investigation_id,

      source_event_id:
        contexto.source_event_id,

      requested_version:
        contexto.requested_version,

      current_version:
        contexto.current_version,

      context_status:
        contexto.context_status,

      is_historical_version:
        contexto.is_historical_version,

      // Contexto integral para fundamentar a futura IA.
      // Dados provenientes do snapshot LAB validado.

      event:
        contexto.event,

      changed_fields:
        contexto.changed_fields,

      severity:
        contexto.event.severity,

      evidence_count:
        contexto.evidence_count,

      indicators:
        contexto.indicators,

      correlations:
        contexto.correlations,

      provenance:
        contexto.provenance,

      decision: {
        eligible_for_ai: elegivel,
        target_workflow: elegivel
          ? "WF-04"
          : null,

        reason: elegivel
          ? "Versao atual validada para revisao."
          : contexto.is_historical_version
            ? "Versao historica. Nao solicitar nova analise."
            : "Tarefa nao elegivel."
      },

      validation_status: "VALID",

      snapshot_mode: true,

      runtime_database_query: false,

      dispatch_status: "MOCK_ONLY",

      real_execution_started: false,

      ai_executed: false,

      notification_sent: false
    }
  };

});
